import{_ as a,o as r,c as l,ag as i}from"./chunks/framework.-Wrcbzkw.js";const g=JSON.parse('{"title":"向量数据库概览","description":"","frontmatter":{},"headers":[],"relativePath":"LLM/向量数据库/01_向量数据库概览.md","filePath":"LLM/向量数据库/01_向量数据库概览.md","lastUpdated":1781077399000}'),e={name:"LLM/向量数据库/01_向量数据库概览.md"};function n(d,t,o,s,h,u){return r(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="向量数据库概览" tabindex="-1">向量数据库概览 <a class="header-anchor" href="#向量数据库概览" aria-label="Permalink to &quot;向量数据库概览&quot;">​</a></h1><h2 id="什么是向量数据库" tabindex="-1">什么是向量数据库？ <a class="header-anchor" href="#什么是向量数据库" aria-label="Permalink to &quot;什么是向量数据库？&quot;">​</a></h2><p>向量数据库是一种专门用于存储、索引和查询高维向量数据的数据库。与传统的关系型数据库不同，向量数据库专注于处理非结构化数据（如文本、图像、音频等）的向量化表示。</p><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><h4 id="_1-向量-embedding" tabindex="-1">1. 向量（Embedding） <a class="header-anchor" href="#_1-向量-embedding" aria-label="Permalink to &quot;1. 向量（Embedding）&quot;">​</a></h4><ul><li>将非结构化数据转换为固定维度的数值向量</li><li>语义相似的数据在向量空间中距离更近</li><li>常见维度：128、256、512、1024、1536 等</li></ul><h4 id="_2-相似度搜索" tabindex="-1">2. 相似度搜索 <a class="header-anchor" href="#_2-相似度搜索" aria-label="Permalink to &quot;2. 相似度搜索&quot;">​</a></h4><ul><li>通过计算向量之间的距离来找到最相似的数据</li><li>常见的距离度量方法： <ul><li><strong>余弦相似度（Cosine Similarity）</strong>：衡量向量方向的相似性</li><li><strong>欧氏距离（Euclidean Distance）</strong>：衡量向量之间的直线距离</li><li><strong>点积（Dot Product）</strong>：综合考虑方向和大小</li></ul></li></ul><h4 id="_3-近似最近邻搜索-ann" tabindex="-1">3. 近似最近邻搜索（ANN） <a class="header-anchor" href="#_3-近似最近邻搜索-ann" aria-label="Permalink to &quot;3. 近似最近邻搜索（ANN）&quot;">​</a></h4><ul><li>精确搜索在大规模数据下太慢</li><li>ANN 算法在精度和速度之间做权衡</li><li>常见算法：HNSW、IVF、FAISS、Annoy 等</li></ul><h2 id="为什么需要向量数据库" tabindex="-1">为什么需要向量数据库？ <a class="header-anchor" href="#为什么需要向量数据库" aria-label="Permalink to &quot;为什么需要向量数据库？&quot;">​</a></h2><h3 id="传统数据库的局限" tabindex="-1">传统数据库的局限 <a class="header-anchor" href="#传统数据库的局限" aria-label="Permalink to &quot;传统数据库的局限&quot;">​</a></h3><ul><li>无法高效处理高维向量数据</li><li>不支持语义相似度搜索</li><li>查询速度随数据量增长急剧下降</li></ul><h3 id="向量数据库的优势" tabindex="-1">向量数据库的优势 <a class="header-anchor" href="#向量数据库的优势" aria-label="Permalink to &quot;向量数据库的优势&quot;">​</a></h3><ol><li><strong>专门优化</strong>：为向量搜索和相似度查询设计</li><li><strong>高效检索</strong>：支持 ANN 算法，实现毫秒级查询</li><li><strong>可扩展</strong>：支持大规模向量数据存储</li><li><strong>丰富功能</strong>：元数据过滤、批量操作、实时更新等</li></ol><h2 id="向量数据库的应用场景" tabindex="-1">向量数据库的应用场景 <a class="header-anchor" href="#向量数据库的应用场景" aria-label="Permalink to &quot;向量数据库的应用场景&quot;">​</a></h2><h3 id="_1-检索增强生成-rag" tabindex="-1">1. 检索增强生成（RAG） <a class="header-anchor" href="#_1-检索增强生成-rag" aria-label="Permalink to &quot;1. 检索增强生成（RAG）&quot;">​</a></h3><ul><li>将知识文档向量化存储</li><li>根据用户查询检索相关文档</li><li>增强 LLM 回答的准确性和时效性</li></ul><h3 id="_2-语义搜索" tabindex="-1">2. 语义搜索 <a class="header-anchor" href="#_2-语义搜索" aria-label="Permalink to &quot;2. 语义搜索&quot;">​</a></h3><ul><li>超越关键词匹配，理解查询意图</li><li>支持自然语言查询</li><li>例如：电商商品搜索、文档检索系统</li></ul><h3 id="_3-推荐系统" tabindex="-1">3. 推荐系统 <a class="header-anchor" href="#_3-推荐系统" aria-label="Permalink to &quot;3. 推荐系统&quot;">​</a></h3><ul><li>基于用户行为和内容相似度推荐</li><li>个性化推荐</li></ul><h3 id="_4-图像-视频搜索" tabindex="-1">4. 图像/视频搜索 <a class="header-anchor" href="#_4-图像-视频搜索" aria-label="Permalink to &quot;4. 图像/视频搜索&quot;">​</a></h3><ul><li>以图搜图</li><li>相似视频检索</li></ul><h3 id="_5-去重和聚类" tabindex="-1">5. 去重和聚类 <a class="header-anchor" href="#_5-去重和聚类" aria-label="Permalink to &quot;5. 去重和聚类&quot;">​</a></h3><ul><li>检测重复内容</li><li>自动数据聚类</li></ul><h2 id="如何选择向量数据库" tabindex="-1">如何选择向量数据库？ <a class="header-anchor" href="#如何选择向量数据库" aria-label="Permalink to &quot;如何选择向量数据库？&quot;">​</a></h2><h3 id="考虑因素" tabindex="-1">考虑因素 <a class="header-anchor" href="#考虑因素" aria-label="Permalink to &quot;考虑因素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>因素</th><th>说明</th></tr></thead><tbody><tr><td><strong>部署方式</strong></td><td>开源自托管 vs 托管服务</td></tr><tr><td><strong>规模</strong></td><td>数据量大小、查询并发量</td></tr><tr><td><strong>功能</strong></td><td>元数据过滤、实时更新、多租户等</td></tr><tr><td><strong>性能</strong></td><td>查询速度、索引构建时间</td></tr><tr><td><strong>成本</strong></td><td>硬件成本、服务费用</td></tr><tr><td><strong>生态</strong></td><td>与 LangChain 等框架的集成</td></tr></tbody></table><h3 id="快速选择指南" tabindex="-1">快速选择指南 <a class="header-anchor" href="#快速选择指南" aria-label="Permalink to &quot;快速选择指南&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th></tr></thead><tbody><tr><td>快速原型开发、小规模数据</td><td>Chroma</td></tr><tr><td>不想管理基础设施</td><td>Pinecone</td></tr><tr><td>企业级大规模应用</td><td>Milvus</td></tr><tr><td>需要模块化架构</td><td>Weaviate</td></tr><tr><td>追求极致性能</td><td>Qdrant</td></tr></tbody></table><h2 id="向量数据库的工作流程" tabindex="-1">向量数据库的工作流程 <a class="header-anchor" href="#向量数据库的工作流程" aria-label="Permalink to &quot;向量数据库的工作流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始数据 → 向量化 → 向量数据库 → 相似度查询 → 结果</span></span>
<span class="line"><span>   ↓           ↓          ↓           ↓</span></span>
<span class="line"><span> 文档     Embedding   索引存储     用户查询</span></span>
<span class="line"><span> 图片      模型       ANN算法      语义搜索</span></span></code></pre></div><h3 id="典型步骤" tabindex="-1">典型步骤 <a class="header-anchor" href="#典型步骤" aria-label="Permalink to &quot;典型步骤&quot;">​</a></h3><ol><li><strong>数据准备</strong>：收集需要索引的文档/数据</li><li><strong>文本分割</strong>：将长文档切分为合适的片段</li><li><strong>向量化</strong>：使用 Embedding 模型将文本转换为向量</li><li><strong>存储索引</strong>：将向量和元数据存入向量数据库</li><li><strong>查询处理</strong>：将用户查询也转换为向量</li><li><strong>相似度搜索</strong>：在向量数据库中查找最相似的向量</li><li><strong>结果返回</strong>：返回相关的原始数据</li></ol><h2 id="核心特性对比" tabindex="-1">核心特性对比 <a class="header-anchor" href="#核心特性对比" aria-label="Permalink to &quot;核心特性对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td><strong>元数据过滤</strong></td><td>结合结构化条件和向量搜索</td></tr><tr><td><strong>混合搜索</strong></td><td>同时支持关键词搜索和向量搜索</td></tr><tr><td><strong>实时更新</strong></td><td>支持向量的动态增删改</td></tr><tr><td><strong>持久化</strong></td><td>数据持久化存储</td></tr><tr><td><strong>分布式</strong></td><td>支持水平扩展</td></tr><tr><td><strong>多语言</strong></td><td>支持多语言向量</td></tr></tbody></table>`,37)])])}const b=a(e,[["render",n]]);export{g as __pageData,b as default};
